class SimpleNN(nn.Module):
    def __init__(self):
        super(SimpleNN, self).__init__()
        self.fc1 = nn.Linear(2, 5)
        self.fc2 = nn.Linear(5, 1)

    def forward(self, x):
        x = torch.relu(self.fc1(x))
        x = self.fc2(x)
        return x


# Generate synthetic dataset
class PeerReviewDataset(Dataset):
    def __init__(self, size, distribution_type):
        if distribution_type == "uniform":
            self.data = np.random.rand(size, 2)  # Uniform distribution
        elif distribution_type == "normal":
            self.data = np.random.normal(
                loc=0.5, scale=0.1, size=(size, 2)
            )  # Normal distribution
            self.data = np.clip(self.data, 0, 1)  # Ensure values are within [0,1]
        elif distribution_type == "skewed":
            self.data = np.random.beta(a=2, b=5, size=(size, 2))  # Skewed distribution
        self.labels = np.random.rand(size)  # RQI labels

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return {
            "features": torch.tensor(self.data[idx], dtype=torch.float32).to(device),
            "label": torch.tensor(self.labels[idx], dtype=torch.float32).to(device),
        }


# Hyperparameter tuning for learning rates
